ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i = 0;
    size_t j = 0;
    size_t compact_index = 0;
    size_t pixel_index = 0;

    while (i < number_compact_pixels && j < number_pixels) {
        switch (depth) {
            case 1:
                for (size_t k = 0; k < 8 && j < number_pixels; ++k) {
                    unsigned char bit = (compact_pixels[compact_index] >> (7 - k)) & 1;
                    pixels[pixel_index++] = bit;
                    ++j;
                }
                ++compact_index;
                break;
            case 2:
                for (size_t k = 0; k < 4 && j < number_pixels; ++k) {
                    unsigned char bits = (compact_pixels[compact_index] >> (6 - k * 2)) & 3;
                    pixels[pixel_index++] = bits;
                    ++j;
                }
                ++compact_index;
                break;
            case 4:
                for (size_t k = 0; k < 2 && j < number_pixels; ++k) {
                    unsigned char bits = (compact_pixels[compact_index] >> ((1 - k) * 4)) & 15;
                    pixels[pixel_index++] = bits;
                    ++j;
                }
                ++compact_index;
                break;
            default:
                return -1;
        }
        ++i;
    }

    return pixel_index;
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i;
    size_t j = 0;
    size_t index = 0;
    size_t bits_per_unit = (size_t)depth;
    size_t bits_per_byte = 8;
    size_t pixels_per_byte = bits_per_byte / bits_per_unit;
    size_t compact_index = 0;

    if ((bits_per_unit != 1) && (bits_per_unit != 2) && (bits_per_unit != 4)) {
        return -1;
    }

    for (i = 0; i < number_compact_pixels && compact_index < number_pixels; i++) {
        unsigned char current_byte = compact_pixels[i];
        for (j = 0; j < pixels_per_byte && compact_index < number_pixels; j++) {
            size_t shift_amount = (bits_per_byte - (j * bits_per_unit)) - bits_per_unit;
            unsigned char pixel_value = (current_byte >> shift_amount) & ((1 << bits_per_unit) - 1);
            pixels[compact_index] = pixel_value;
            compact_index++;
        }
    }

    return (ssize_t)compact_index;
}

ssize_t decode_compact_pixels(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t compact_index = 0;
    size_t pixel_index = 0;

    while (compact_index < number_compact_pixels && pixel_index < number_pixels) {
        unsigned char value = compact_pixels[compact_index++];

        switch (depth) {
            case 1:
                for (int i = 0; i < 8 && pixel_index < number_pixels; ++i) {
                    pixels[pixel_index++] = (value >> (7 - i)) & 1;
                }
                break;
            case 2:
                for (int i = 0; i < 4 && pixel_index < number_pixels; ++i) {
                    pixels[pixel_index++] = (value >> (6 - 2 * i)) & 3;
                }
                break;
            case 4:
                for (int i = 0; i < 2 && pixel_index < number_pixels; ++i) {
                    pixels[pixel_index++] = (value >> (4 * (1 - i))) & 15;
                }
                break;
            default:
                return -1;
        }
    }

    return (ssize_t)pixel_index;
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i, j;
    size_t bits_per_unit = (size_t)depth;
    size_t compact_index = 0;
    size_t pixel_index = 0;
    size_t bits_remaining = 0;
    unsigned char compact_value = 0;
    unsigned char mask = (1 << depth) - 1;

    while (compact_index < number_compact_pixels && pixel_index < number_pixels) {
        if (bits_remaining < bits_per_unit) {
            if (compact_index >= number_compact_pixels) break;
            compact_value = compact_pixels[compact_index++];
            bits_remaining = 8;
        }

        size_t bits_to_use = (bits_remaining < bits_per_unit) ? bits_remaining : bits_per_unit;
        unsigned char value = (compact_value >> (bits_remaining - bits_to_use)) & mask;
        pixels[pixel_index++] = value;

        bits_remaining -= bits_to_use;
    }

    return (ssize_t)pixel_index;
}

ssize_t decode_compact_pixels(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t src_index = 0;
    size_t dst_index = 0;

    while (src_index < number_compact_pixels && dst_index < number_pixels) {
        switch (depth) {
            case 1:
                for (size_t i = 0; i < 8 && dst_index < number_pixels; ++i) {
                    pixels[dst_index++] = (compact_pixels[src_index] >> (7 - i)) & 0x01;
                }
                ++src_index;
                break;
            case 2:
                for (size_t i = 0; i < 4 && dst_index < number_pixels; ++i) {
                    pixels[dst_index++] = (compact_pixels[src_index] >> (6 - (i * 2))) & 0x03;
                }
                ++src_index;
                break;
            case 4:
                for (size_t i = 0; i < 2 && dst_index < number_pixels; ++i) {
                    pixels[dst_index++] = (compact_pixels[src_index] >> ((1 - i) * 4)) & 0x0F;
                }
                ++src_index;
                break;
            default:
                return -1;
        }
    }

    return (ssize_t)dst_index;
}
